import struct, pathlib
for name in ['TestAVAR.ttf','TestGVARNine.ttf','Zycon.ttf','TestGVAREight.ttf']:
 p=pathlib.Path('repo-vul/src-vul/font-corpus')/name; b=p.read_bytes(); n=struct.unpack('>H',b[4:6])[0]; tabs={}
 for i in range(n):
  off=12+16*i; tag=b[off:off+4].decode('latin1'); cs,to,ln=struct.unpack('>III',b[off+4:off+16]); tabs[tag]=(to,ln,cs)
 print('\n',name,'tables',sorted(tabs))
 for tag in ['maxp','head','hhea','loca','glyf','fvar','gvar','avar']:
  if tag in tabs:
   o,l,_=tabs[tag]; print(tag,o,l,b[o:o+min(l,64)].hex())
 # loca offsets
 if 'loca' in tabs and 'head' in tabs:
  fmt=struct.unpack('>h', b[tabs['head'][0]+50:tabs['head'][0]+52])[0]
  ng=struct.unpack('>H', b[tabs['maxp'][0]+4:tabs['maxp'][0]+6])[0]
  lo=tabs['loca'][0]
  offs=[]
  if fmt==0:
   offs=[struct.unpack('>H', b[lo+2*i:lo+2*i+2])[0]*2 for i in range(ng+1)]
  else:
   offs=[struct.unpack('>I', b[lo+4*i:lo+4*i+4])[0] for i in range(ng+1)]
  print('loca fmt',fmt,'ng',ng,'offs',offs[:20])
  go=tabs['glyf'][0]
  for gi in range(min(ng,10)):
   s,e=offs[gi],offs[gi+1]
   if e>s: print(' glyph',gi,'len',e-s,'hdr',struct.unpack('>hhhhh',b[go+s:go+s+10]))
PY

